// Parse RSS items, keep only those naming the company (exact name or domain stem), add LinkedIn posts. No LLM if nothing to classify.
const a = $('Load accounts for news').item.json;
const xml = String($json.body || '');
const norm = s => String(s || '').toLowerCase().replace(/\b(ltd|limited|llp|plc|uk|group|holdings)\b/g, '').replace(/[^a-z0-9]/g, '');
const brand = String(a.name || '').split(/\s+[-|:]\s+/)[0].replace(/\s+(ltd|limited|llp|plc)\.?$/i, '').trim();
const stem = a.domain ? String(a.domain).split('.')[0] : '';
const un = s => String(s || '').replace(/<!\[CDATA\[|\]\]>/g, '').replace(/&amp;/g, '&').replace(/&#39;/g, "'").replace(/&quot;/g, '"').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
const items = [];
const re = /<item>([\s\S]*?)<\/item>/g; let m;
while ((m = re.exec(xml)) && items.length < 12) {
  const b = m[1];
  const title = un((b.match(/<title>([\s\S]*?)<\/title>/) || [,''])[1]);
  const link = un((b.match(/<link>([\s\S]*?)<\/link>/) || [,''])[1]);
  const date = un((b.match(/<pubDate>([\s\S]*?)<\/pubDate>/) || [,''])[1]);
  const desc = un((b.match(/<description>([\s\S]*?)<\/description>/) || [,''])[1]).slice(0, 300);
  const hay = (title + ' ' + desc).toLowerCase();
  const named = (brand.length >= 4 && hay.includes(brand.toLowerCase())) || (stem.length >= 5 && norm(hay).includes(norm(stem)));
  if (named) items.push({ source: 'news', title, url: link, date: date ? new Date(date).toISOString().slice(0, 10) : null, text: desc });
}
for (const p of (a.posts || [])) {
  if (!p || !p.text) continue;
  items.push({ source: 'post', title: '', url: p.url || ('linkedin-post:' + (p.date || '') + ':' + String(p.text).slice(0, 40)), date: p.date ? String(p.date).slice(0, 10) : null, text: String(p.text).slice(0, 500) });
}
return { json: { account_id: a.account_id, name: a.name, industry: a.li_industry, hq: a.hq_country, items, n: items.length } };
